// e2-orientation-core.js
/* Rotation about a sigma bond preserves each carbon's cyclic substituent order. */
(()=>{'use strict';
const groups={H:{name:'hydrogen',label:'H'},Me:{name:'methyl',label:'Me'},Ph:{name:'phenyl',label:'Ph'},Et:{name:'ethyl',label:'Et'},Pr:{name:'propyl',label:'Pr'},Cl:{name:'chlorine',label:'Cl'},Br:{name:'bromine',label:'Br'},I:{name:'iodine',label:'I'}};
const configs=[
 ['Br','H','Me','H','Me'],['Cl','H','Et','Me','Et'],['I','Me','Me','H','Et'],['Br','H','Ph','Me','Me'],
 ['Cl','Me','Et','H','Ph'],['Br','Me','Ph','Me','Et'],['I','H','Me','H','Ph'],['Cl','H','H','Me','Ph'],
 ['Br','Me','Me','Me','Pr'],['I','H','Et','H','Me'],['Cl','Me','Ph','H','Pr'],['Br','Et','Ph','Me','Me'],
 ['I','H','Ph','H','Et'],['Br','H','Et','Me','Ph'],['Cl','Me','Me','H','Me'],['I','Me','Et','Me','Ph'],
 ['Br','H','Pr','H','Me'],['Cl','H','Ph','Me','Et'],['I','Me','Ph','H','Ph'],['Br','Me','Et','Me','Me']
];
const rotate=(values,k)=>values.map((_,i)=>values[(i+k)%3]);
const cyclic=(a,b)=>[0,1,2].some(k=>rotate(a,k).every((v,i)=>v===b[i]));
const bank=configs.map((v,i)=>{const [lg,a1,a2,b1,b2]=v,a=[lg,a1,a2],b=['H',b1,b2];let sourceA,sourceB;for(let j=0;j<9;j++){sourceA=rotate(a,(i*2+1)%3);sourceB=rotate(b,(i+j)%3);if(sourceB[sourceA.indexOf(lg)]!=='H')break;}return{id:'eo-'+(i+1),lg,a,b,sourceA,sourceB,pieces:[a1,a2,b1,b2],flipX:i%3===1,flipY:i%4===3};});
let seed=82157;for(let i=bank.length-1;i>0;i--){seed=(1664525*seed+1013904223)>>>0;const j=seed%(i+1);[bank[i],bank[j]]=[bank[j],bank[i]];}const first=bank.findIndex(q=>q.id==='eo-1');[bank[0],bank[first]]=[bank[first],bank[0]];
function normalize(q,values){if(values.length===4)return values;const a=values.slice(0,3),b=values.slice(3),k=a.indexOf(q.lg);if(k<0||b[k]!=='H')return null;return [...rotate(a,k).slice(1),...rotate(b,k).slice(1)];}
function result(q,values){if(values.length===6){if(values.some(v=>!v))return{correct:false,message:'Fill all six positions, including the beta H and leaving group, before checking.'};const a=values.slice(0,3),b=values.slice(3);if(!cyclic(q.sourceA,a)||!cyclic(q.sourceB,b))return{correct:false,message:'Keep each group on its original carbon and preserve its configuration. Rotate groups together; do not swap two groups.'};if(!normalize(q,values))return{correct:false,message:'The beta H and leaving group are not antiperiplanar. Rotate about C–C so their bonds are 180° apart.'};return{correct:true,message:'Correct. The beta H and leaving group are antiperiplanar, with the original configuration preserved.'};}if(values.some(v=>!v))return{correct:false,message:'Fill all four positions before checking.'};const a=[q.lg,values[0],values[1]],b=['H',values[2],values[3]];if(!cyclic(q.sourceA,a)||!cyclic(q.sourceB,b))return{correct:false,message:'Keep each group on its original carbon. Rotate the three groups together without swapping two groups: swapping them changes the stereochemistry.'};return{correct:true,message:'Correct. The same molecule is reoriented with the beta H and leaving group antiperiplanar (180° apart).'};}
const point=(a,theta,length=110)=>({x:a.x+length*Math.cos(theta),y:a.y+length*Math.sin(theta)}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const centres=[{x:335,y:300},{x:335+110*Math.cos(Math.PI/6),y:355}],angles=[[5*Math.PI/6,4*Math.PI/3,5*Math.PI/3],[11*Math.PI/6,Math.PI/3,2*Math.PI/3]],types=[['line','hash','wedge'],['line','wedge','hash']];
function layout(q,values){const transform=p=>({x:q.flipX?800-p.x:p.x,y:q.flipY?650-p.y:p.y});const c=centres.map(transform),branches=[];for(let side=0;side<2;side++)for(let slot=0;slot<3;slot++){const value=values[side*3+slot],theta=angles[side][slot],start=centres[side],tip=point(start,theta),path=[start,tip];if(groups[value]?.length){const bend=(side===0&&slot===1)||(side===1&&slot===1)?-Math.PI/3:Math.PI/3;for(let k=1;k<groups[value].length;k++)path.push(point(path.at(-1),theta+(k%2?bend:0)));}branches.push({side,slot,value,type:types[side][slot],path:path.map(transform),tip:transform(tip)});}return{centres:c,branches};}
function stereo(a,b,type){const dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy),px=-dy/n,py=dx/n;if(type==='wedge')return `<path d="M${a.x} ${a.y}L${b.x+px*9} ${b.y+py*9}L${b.x-px*9} ${b.y-py*9}Z" fill="#172532"/>`;if(type==='hash')return Array.from({length:7},(_,i)=>{const t=(i+1)/7,w=9*t,x=a.x+dx*t,y=a.y+dy*t;return `<path d="M${x-px*w} ${y-py*w}L${x+px*w} ${y+py*w}" stroke="#172532" stroke-width="1.6"/>`;}).join('');return `<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#172532" stroke-width="2" fill="none"/>`;}
function diagram(q,values,interactive=false,locked=false,allSlots=false){const l=layout(q,values);let s=stereo(...l.centres,'line');for(const b of l.branches){const [a,p]=b.path,dx=p.x-a.x,dy=p.y-a.y,n=Math.hypot(dx,dy),ux=dx/n,uy=dy/n,blank=!b.value,descriptor=groups[b.value],label=descriptor?.label;let gap=0;if(blank){gap=Math.min(Math.abs(ux)>1e-8?30/Math.abs(ux):Infinity,Math.abs(uy)>1e-8?23/Math.abs(uy):Infinity)+12;}else if(label){gap=Math.min(Math.abs(ux)>1e-8?(label==='H'?12:20)/Math.abs(ux):Infinity,Math.abs(uy)>1e-8?15/Math.abs(uy):Infinity)+5;}if(label&&b.type==='hash')gap+=10;s+=stereo(a,{x:p.x-ux*gap,y:p.y-uy*gap},b.type);for(let k=2;k<b.path.length;k++)s+=stereo(b.path[k-1],b.path[k],'line');if(label)s+=`<text x="${p.x}" y="${p.y}" text-anchor="middle" dominant-baseline="central" font-family="Arial,sans-serif" font-size="26" fill="#172532">${label}</text>`;if(interactive&&(allSlots||b.slot!==0)){const index=allSlots?b.side*3+b.slot:b.side*2+b.slot-1,name=(b.side===0?'Halogen-bearing':'Beta')+' carbon '+b.type+' position';s+=`<g class="eo-slot${blank?' empty':''}" data-eo-slot="${index}" role="button" tabindex="${locked?-1:0}" aria-disabled="${locked}" aria-label="${esc(name+(blank?': empty':': '+descriptor.name+'. Select to remove'))}"><rect x="${p.x-30}" y="${p.y-23}" width="60" height="46" rx="4" fill="${blank?'#f7faff':'transparent'}" stroke="${blank?'#a9bed7':'transparent'}" stroke-width="1.5"/>${blank?`<text x="${p.x}" y="${p.y}" text-anchor="middle" dominant-baseline="central" font-family="Arial,sans-serif" font-size="24" fill="#52657c">+</text>`:''}</g>`;}}
return `<svg class="eo-diagram" xmlns="http://www.w3.org/2000/svg" viewBox="180 150 440 350" role="group" aria-label="${interactive?'Place the groups to reorient the same molecule with a beta H and leaving group antiperiplanar.':'Starting perspective structure. Rotate about the central carbon–carbon bond.'}">${s}</svg>`;}
function piece(value){const d=groups[value];if(d.label)return `<span>${esc(d.label)}</span>`;const points=d.length===2?[[8,45],[42,25],[76,45]]:[[5,45],[34,28],[63,45],[92,28]];return `<svg viewBox="0 0 100 70" width="78" height="52" aria-hidden="true"><path d="${points.map((p,i)=>(i?'L':'M')+p.join(' ')).join('')}" stroke="currentColor" stroke-width="2.2" fill="none"/></svg>`;}
globalThis.E2Orientation={bank,groups,rotate,cyclic,normalize,result,layout,diagram,piece};
})();

;
// e2-orientation.js
(()=>{'use strict';const $=id=>document.getElementById(id),api=E2Orientation,bank=api.bank,drafts=new Map(),done=new Set();let index=0,selected=null;const current=()=>bank[index],fresh=()=>({placed:Array(6).fill(null),correct:false,hints:0});let state=fresh();
function save(){drafts.set(current().id,state);}
function feedback(message='',status=''){$('eo-feedback').textContent=message;$('eo-feedback').dataset.state=status;}
function draw(){const q=current();$('eo-source').innerHTML=api.diagram(q,[...q.sourceA,...q.sourceB]);const values=state.placed.map(p=>p?.value);$('eo-target').innerHTML=api.diagram(q,values,true,state.correct,true);$('eo-pieces').innerHTML=[...q.a,...q.b].map((value,i)=>{const used=state.placed.some(p=>p?.id===i),d=api.groups[value];return `<button type="button" class="eo-piece" data-eo-piece="${i}" aria-label="${d.name} group ${i+1}" aria-pressed="${selected===i}" draggable="${!used&&!state.correct}" ${used||state.correct?'disabled':''}>${api.piece(value)}</button>`;}).join('');$('eo-check').disabled=state.correct;$('eo-clear').disabled=state.correct||!state.placed.some(Boolean);$('eo-prev').disabled=index===0;$('eo-next').disabled=index===bank.length-1;$('eo-count').textContent=`QUESTION ${index+1} / ${bank.length}`;$('eo-score').textContent=`Completed: ${done.size} / ${bank.length}`;$('eo-progress').style.width=done.size/bank.length*100+'%';$('eo-title').textContent=`Question ${index+1}`;$('eo-question').value=index;}
function begin(i){save();index=i;state=drafts.get(current().id)||fresh();selected=null;draw();feedback(state.correct?api.result(current(),state.placed.map(p=>p?.value)).message:'',state.correct?'correct':'');}
function assign(piece,slot){if(state.correct||!Number.isInteger(piece)||!Number.isInteger(slot)||piece<0||piece>5||slot<0||slot>5)return;const prior=state.placed.findIndex(p=>p?.id===piece);if(prior>=0)state.placed[prior]=null;state.placed[slot]={id:piece,value:[...current().a,...current().b][piece]};selected=null;save();feedback();draw();}
function chooseSlot(slot){if(state.correct)return;if(selected!==null){assign(selected,slot);return;}if(state.placed[slot]){state.placed[slot]=null;save();feedback();draw();}}
$('eo-pieces').addEventListener('click',e=>{const b=e.target.closest('[data-eo-piece]');if(!b||b.disabled)return;selected=selected===+b.dataset.eoPiece?null:+b.dataset.eoPiece;draw();$('eo-pieces').querySelector?.('[data-eo-piece="'+b.dataset.eoPiece+'"]')?.focus?.();});
$('eo-pieces').addEventListener('dragstart',e=>{const b=e.target.closest('[data-eo-piece]');if(!b||b.disabled){e.preventDefault();return;}e.dataTransfer.setData('text/plain',b.dataset.eoPiece);e.dataTransfer.effectAllowed='move';});
$('eo-target').addEventListener('click',e=>{const b=e.target.closest('[data-eo-slot]');if(b)chooseSlot(+b.dataset.eoSlot);});$('eo-target').addEventListener('keydown',e=>{const b=e.target.closest('[data-eo-slot]');if(b&&['Enter',' '].includes(e.key)){e.preventDefault();chooseSlot(+b.dataset.eoSlot);$('eo-target').querySelector?.('[data-eo-slot="'+b.dataset.eoSlot+'"]')?.focus?.();}});$('eo-target').addEventListener('dragover',e=>{if(!state.correct)e.preventDefault();});$('eo-target').addEventListener('drop',e=>{e.preventDefault();const slot=e.target.closest('[data-eo-slot]'),raw=e.dataTransfer.getData('text/plain');if(slot&&/^[0-5]$/.test(raw))assign(+raw,+slot.dataset.eoSlot);});
$('eo-check').addEventListener('click',()=>{if(state.correct)return;const r=api.result(current(),state.placed.map(p=>p?.value));if(r.correct){state.correct=true;done.add(current().id);selected=null;save();draw();}feedback((r.correct?'':'Incorrect. ')+r.message,r.correct?'correct':'incorrect');});
$('eo-hint').addEventListener('click',()=>{state.hints=Math.min(2,state.hints+1);save();feedback(state.hints===1?'Hint: place every group, including H and the leaving group. They must remain on their original carbons; the beta H and leaving group need to be 180° apart.':'Hint: rotating about C–C cycles all three groups on a carbon together. Keep their order around that carbon; swapping two groups would invert its configuration. If two beta hydrogens are available, either valid anti rotation is accepted.');});
$('eo-clear').addEventListener('click',()=>{if(state.correct)return;state.placed=Array(6).fill(null);selected=null;save();feedback();draw();});$('eo-prev').addEventListener('click',()=>{if(index>0)begin(index-1);});$('eo-next').addEventListener('click',()=>{if(index<bank.length-1)begin(index+1);});$('eo-question').addEventListener('change',e=>{const i=+e.target.value;if(Number.isInteger(i)&&i>=0&&i<bank.length)begin(i);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;draw();}});
$('eo-question').innerHTML=bank.map((_,i)=>`<option value="${i}">Question ${i+1}</option>`).join('');draw();
})();
